-- Already applied. UG official entry requirements page (admissions.ug.edu.gh/undergraduate/entry-requirements), via ChatGPT reply (reply was cut off after the Engineering Sciences Materials row).
with ug as (select p.id, p.name from public.programs p join public.schools s on s.id=p.school_id where s.name='University of Ghana')
, u1 as (update public.program_requirements r set min_grade='B3' from ug where r.program_id=ug.id and r.subject='Elective Mathematics' and ug.name in ('BSc Actuarial Science','BSc Computer Science','BSc Materials Science and Engineering (Engineering Sciences)') returning 1)
, u2 as (update public.program_requirements r set min_grade='C4' from ug where r.program_id=ug.id and r.subject='Elective Mathematics' and ug.name='Bachelor of Education in Engineering' returning 1)
, u3 as (update public.program_requirements r set min_grade='C6' from ug where r.program_id=ug.id and r.min_grade is null and r.subject in ('Chemistry','Biology') and ug.name in ('Bachelor of Medicine and Bachelor of Surgery (MBChB)','Doctor of Veterinary Medicine') returning 1)
, i1 as (insert into public.program_requirements (program_id,subject,min_grade,is_core,any_of_group,any_of_need) select ug.id,x.s,'C6',false,1,2 from ug, (values ('Physics'),('Biology'),('Elective Mathematics')) x(s) where ug.name='Bachelor of Medicine and Bachelor of Surgery (MBChB)' and not exists (select 1 from public.program_requirements r where r.program_id=ug.id and r.subject=x.s) returning 1)
, i2 as (insert into public.program_requirements (program_id,subject,min_grade,is_core,any_of_group,any_of_need) select ug.id,x.s,'C6',false,1,1 from ug, (values ('Physics'),('Elective Mathematics')) x(s) where ug.name='Doctor of Veterinary Medicine' and not exists (select 1 from public.program_requirements r where r.program_id=ug.id and r.subject=x.s) returning 1)
select 1;
